    /// @notice Checks if a delegate has been granted full permissions (delegateForAll) for a specific address.
    /// @param to The address of the delegate being checked.
    /// @param from The address of the delegator (the one who granted permissions).
    /// @return isValid A boolean indicating whether the delegate has full permissions.
    function checkDelegateForAll(address to, address from) internal view returns (bool isValid) {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            mstore(0x40, from)
            mstore(0x2c, shl(96, to))
            // `checkDelegateForAll(address,address,bytes32)`.
            mstore(0x0c, 0x28474167)
            if iszero(
                and(gt(returndatasize(), 0), mload(staticcall(gas(), DELEGATE_REGISTRY_V2, 0x22, 0x44, 0x00, 0x20)))
            ) {
                // `checkDelegateForAll(address,address)`.
                mstore(0x00, 0xd2ce7d65)
                isValid := mload(
                    staticcall(gas(), DELEGATE_REGISTRY_V1, 0x1c, 0x44, 0x01, 0x20)
                )
            }
            isValid := mload(0x00)
            mstore(0x40, m) // Restore the free memory pointer.
        }
    }

    /// @notice Checks if a delegate has been granted full permissions (delegateForAll) for a specific address.
    /// @param to The address of the delegate being checked.
    /// @param from The address of the delegator (the one who granted permissions).
    /// @param rights The rights to check.
    /// @return isValid A boolean indicating whether the delegate has full permissions.
    function checkDelegateForAll(address to, address from, bytes32 rights)
        internal
        view
        returns (bool isValid)
    {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            mstore(0x40, from)
            mstore(0x2c, shl(96, to))
            mstore(0x0c, rights)
            // `checkDelegateForAll(address,address,bytes32)`.
            mstore(0x00, 0x28474167)
            isValid := mload(
                staticcall(gas(), DELEGATE_REGISTRY_V2, 0x00, 0x64, 0x01, 0x20)
            )
            if iszero(isValid) {
                // `checkDelegateForAll(address,address)`.
                mstore(0x00, 0xd2ce7d65)
                mstore(0x2c, from)
                mstore(0x10, shl(96, to))
