    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Checks the delegated rights for an ERC1155 token between two addresses.
    /// @param to The address to which the rights are delegated.
    /// @param from The address from which the rights are delegated.
    /// @param contract_ The address of the ERC1155 contract.
    /// @param id The ID of the ERC1155 token.
    /// @return amount The amount of delegated rights, if any.
    function checkDelegateForERC1155(address to, address from, address contract_, uint256 id)
        internal
        view
        returns (uint256 amount)
    {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            mstore(0x40, id)
            mstore(0x24, from)
            mstore(0x08, shl(96, to))
            mstore(0x18, contract_)
            // `checkDelegateForERC1155(address,address,address,uint256,bytes32)`.
            mstore(0x00, 0xa6868687)
            if iszero(
                and(
                    gt(returndatasize(), 0),
                    mload(staticcall(gas(), DELEGATE_REGISTRY_V2, 0x00, 0x84, 0x00, 0x20))
                )
            ) {
                // `checkDelegateForToken(address,address,address,uint256)`.
                mstore(0x00, 0xe4665e11)
                mstore(0x2c, from)
                mstore(0x10, shl(96, to))
                mstore(0x30, contract_)
                mstore(0x50, id)
                amount := mload(
                    staticcall(gas(), DELEGATE_REGISTRY_V1, 0x1c, 0x84, 0x01, 0x20)
                )
            }
            amount := mul(amount, mload(0x00))
            mstore(0x40, m) // Restore the free memory pointer.
        }
    }

    /// @notice Checks the delegated rights for an ERC1155 token between two addresses.
    /// @param to The address to which the rights are delegated.
    /// @param from The address from which the rights are delegated.
    /// @param contract_ The address of the ERC1155 contract.
    /// @param id The ID of the ERC1155 token.
    /// @param rights The specific rights being checked.
    /// @return amount The amount of delegated rights, if any.
    function checkDelegateForERC1155(
        address to,
        address from,
        address contract_,
        uint256 id,
        bytes32 rights
    ) internal view returns (uint256 amount) {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            mstore(0x40, id)
            mstore(0x24, from)
            mstore(0x08, shl(96, to))
            mstore(0x18, contract_)
            mstore(0x64, rights)
            // `checkDelegateForERC1155(address,address,address,uint256,bytes32)`.
            mstore(0x00, 0xa6868687)
            amount := mload(
                staticcall(gas(), DELEGATE_REGISTRY_V2, 0x00, 0x84, 0x01, 0x20)
            )
            if iszero(amount) {
                // `checkDelegateForToken(address,address,address,uint256)`.
                mstore(0x00, 0xe4665e11)
                mstore(0x2c, from)
                mstore(0x10, shl(96, to))
                mstore(0x30, contract_)
                mstore(0x50, id)
                amount := mload(
                    staticcall(gas(), DELEGATE_REGISTRY_V1, 0x1c, 0x84, 0x01, 0x20)
                )
            }
            mstore(0x40, m) // Restore the free memory pointer.
        }
    }
}

